(()=>{src=document.getElementById("garfield-clock-script").src.replace("/script.min.js","");let e=document.createElement("link");e.rel="stylesheet",e.type="text/css",e.href=`${src}/style.min.css`,document.getElementById("garfield-clock-script").after(e)})(),window.addEventListener("load",()=>{(()=>{let e=new Date,t=e.getHours(),l=e.getMinutes(),r=e.getSeconds();var c=6*r,s=6*l+.1*r,n=30*t+.5*l,o=document.getElementsByClassName("garfield-analog-clock");!function e(){c+=6,s+=.1,n+=.1/60;for(let e=0;e<o.length;e++){let t=o[e];t.querySelector(".second").style.rotate=c+"deg",t.querySelector(".minute").style.rotate=s+"deg",t.querySelector(".hour").style.rotate=n+"deg"}setTimeout(e,1e3)}()})()});